  })

  it('G02-D08 size 字段与字节数不一致时，仍按 base64 解出两帧', async () => {
    expectedWarnings = [
      [
        '[dialog-assets] portraits failed, skip:',
        new Error('dialog-assets: portraits.json fetch failed (404)'),
      ],
    ]
    vi.stubGlobal(
      'fetch',
      vi.fn(async (input: RequestInfo | URL) => {
